  'prompt.missingVars': { 'zh-CN': '以下变量在原模板中使用但在当前内容中未找到：{vars}，可能导致渲染时出现未替换的占位符。', 'en-US': 'Variables in template not found in current content: {vars}. May cause unreplaced placeholders.', 'ru-RU': 'Переменные не найдены: {vars}. Возможны незаменённые заполнители.' },
  'prompt.unknownVars': { 'zh-CN': '以下变量不在模板变量列表中，渲染时不会被替换：{vars}（若为拼写错误请修正；若为自定义占位符请忽略此提示）', 'en-US': 'Variables not defined in template, they will NOT be replaced at render time: {vars} (fix typos, or ignore if intended)', 'ru-RU': 'Переменные не определены в шаблоне и НЕ будут заменены: {vars} (исправьте опечатки или проигнорируйте)' },
