  'prompt.savedProject': { 'zh-CN': '已保存到当前项目', 'en-US': 'Saved to current project', 'ru-RU': 'Сохранено в проект' },
  'prompt.restoredDefault': { 'zh-CN': '已恢复为内置默认', 'en-US': 'Restored to built-in default', 'ru-RU': 'Восстановлено по умолчанию' },
  'prompt.restoreDefaultTitle': { 'zh-CN': '恢复默认模板', 'en-US': 'Restore Default Template', 'ru-RU': 'Восстановить шаблон по умолчанию' },
  'prompt.restoreDefaultConfirm': { 'zh-CN': '将删除该模板的全局与项目级自定义内容，恢复为内置版本。自定义内容删除后不可恢复，确定继续吗？', 'en-US': 'This will delete the global and project-level custom content and restore the built-in template. Custom content cannot be recovered. Continue?', 'ru-RU': 'Будут удалены пользовательские версии (глобальная и проектная) и восстановлен встроенный шаблон. Удалённые данные невосстановимы. Продолжить?' },
  'prompt.customLangTip': { 'zh-CN': '自定义模板显示保存时的内容，不随界面语言切换；如需其他语言请在对应语言界面下重新保存', 'en-US': 'Custom templates show the content saved at the time; they do not follow the UI language. Re-save under another language to change it', 'ru-RU': 'Пользовательский шаблон показывает сохранённое содержимое и не меняется при смене языка интерфейса. Пересохраните на нужном языке' },
  'prompt.tip': { 'zh-CN': '提示', 'en-US': 'Note', 'ru-RU': 'Примечание' },
  'prompt.saveFailed': { 'zh-CN': '保存失败', 'en-US': 'Save failed', 'ru-RU': 'Ошибка сохранения' },
  'prompt.needProjectTip': { 'zh-CN': '请先打开一个项目', 'en-US': 'Please open a project first', 'ru-RU': 'Сначала откройте проект' },
  'agent.subtitle': { 'zh-CN': '你的 AI 创作助手 — 支持 / 命令和 @ 引用', 'en-US': 'Your AI creation assistant — supports / commands and @ mentions', 'ru-RU': 'Ваш ИИ-ассистент — поддержка /команд и @ссылок' },
  'agent.disclaimer': { 'zh-CN': 'AI 生成内容仅供参考，重要信息请自行核实。', 'en-US': 'AI-generated content is for reference only. Verify important information.', 'ru-RU': 'Контент ИИ — только для справки. Проверяйте важную информацию.' },
  'agent.aiWorkflow': { 'zh-CN': '工作流输出', 'en-US': 'Workflow Output', 'ru-RU': 'Вывод рабочего процесса' },
  'agent.allConversations': { 'zh-CN': '全部对话', 'en-US': 'All conversations', 'ru-RU': 'Все диалоги' },
  'agent.noConversations': { 'zh-CN': '暂无对话记录', 'en-US': 'No conversation history', 'ru-RU': 'Нет истории диалогов' },
  'agent.deleteConversation': { 'zh-CN': '删除对话', 'en-US': 'Delete conversation', 'ru-RU': 'Удалить диалог' },
  'agent.confirmClearTitle': { 'zh-CN': '清空对话记录', 'en-US': 'Clear conversation history', 'ru-RU': 'Очистить историю диалогов' },
