  'inject.ctxWordsPerChapter': { 'zh-CN': '- 每章字数：{value} 字', 'en-US': '- Words per chapter: {value}', 'ru-RU': '- Слов на главу: {value}' },
  'inject.ctxCoreOutline': { 'zh-CN': '- 核心大纲：{value}', 'en-US': '- Core outline: {value}', 'ru-RU': '- Основной план: {value}' },
  'inject.ctxWorldSetting': { 'zh-CN': '- 世界观设定：{value}', 'en-US': '- World setting: {value}', 'ru-RU': '- Мир: {value}' },
